package com.hrm.service;import com.hrm.config.DBConnection;import java.sql.*;public class MaintenanceService{public String testConnection(){try(Connection c=DBConnection.getConnection()){return "Kết nối MySQL OK: "+c.getMetaData().getDatabaseProductVersion();}catch(Exception e){return "Lỗi: "+e.getMessage();}}public String systemStats()throws Exception{try(Connection c=DBConnection.getConnection();Statement s=c.createStatement()){String[] t={"employees","users","payrolls","projects","project_allocations","employment_events"};StringBuilder b=new StringBuilder("THỐNG KÊ HỆ THỐNG: ");for(String x:t){try(ResultSet r=s.executeQuery("SELECT COUNT(*) FROM "+x)){r.next();b.append(x).append("=").append(r.getInt(1)).append("; ");}}return b.toString();}}public String optimize()throws Exception{try(Connection c=DBConnection.getConnection();Statement s=c.createStatement()){s.execute("OPTIMIZE TABLE employees,users,payrolls,project_allocations,employment_events,rewards_disciplines,attendance_records,leave_records,overtime_records");return "Đã tối ưu các bảng nghiệp vụ.";}}}
